boxes.text:
dictionary format:
{
   "control" : { control opcodes },
  "global" : { global opcodes, apply to all regions + groups }
  "groups: [ 
     {
        group opcodes that apply to all regions defined below
        "regions" : [
             array of region dictionaries
         ]
   },
   "regions" : [
      { "key" : 60, "sample" : "filename" etc. }
   ]
}
